def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    sep_colors = {grid[r][0] for r in sep_rows}
    sep_colors.update(grid[0][c] for c in sep_cols)

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]

    counts = {}
    for r in range(h):
        for c in range(w):
            if r not in sep_rows and c not in sep_cols:
                color = grid[r][c]
                counts[color] = counts.get(color, 0) + 1

    background = max(counts, key=counts.get)
    foregrounds = [color for color in counts if color != background]
    foreground = foregrounds[0] if foregrounds else None

    out = []
    for i in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[i] + 1, row_bounds[i + 1]
        row = []
        for j in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[j] + 1, col_bounds[j + 1]
            n = sum(
                grid[r][c] == foreground
                for r in range(r0, r1)
                for c in range(c0, c1)
            ) if foreground is not None else 0
            row.append(1 if n >= 2 else background)
        out.append(row)

    return out
